}

final class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {
  override def tokenize(value: NumericValue): Token = {
    val strValue = value match {
      case NumericValue.Decimal(v) => formatDecimal(v)
      case NumericValue.Floating(v, _) => formatFloating(v)
      case NumericValue.Integral(v, _) => v.toString
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.originalType))
  }

  def tokenize(value: Int): Token = tokenize(NumericValue.Integral(value.toLong, "int"))
  def tokenize(value: Long): Token = tokenize(NumericValue.Integral(value, "int"))
  def tokenize(value: Short): Token = tokenize(NumericValue.Integral(value.toLong, "int"))
  def tokenize(value: Byte): Token = tokenize(NumericValue.Integral(value.toLong, "int"))
  def tokenize(value: Double): Token = tokenize(NumericValue.Floating(value, "float"))
  def tokenize(value: Float): Token = tokenize(NumericValue.Floating(value.toDouble, "float"))
  def tokenize(value: BigDecimal): Token = tokenize(NumericValue.Decimal(value))
  def tokenize(value: java.math.BigDecimal): Token = tokenize(BigDecimal(value))

  private def formatDecimal(value: BigDecimal): String =
    value.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString

  private def formatFloating(value: Double): String =
    f"$value%.${precision}f"

  // formatOptions retained for parity; not used in this implementation
  private val _formatOptions = formatOptions
}

// ============================================================================
// Temporal tokenizer
// ============================================================================

final class TemporalTokenizer(formatStr: Option[String] = None)
    extends BaseTokenizer[TemporalAccessor] {
  private val isoFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")
  private val customFormatter = formatStr.map(DateTimeFormatter.ofPattern)

  override def tokenize(value: TemporalAccessor): Token = {
    val formatter = customFormatter.getOrElse {
      value match {
        case _: LocalDateTime => isoFormatter
        case _: LocalDate => dateFormatter
        case _ => dateFormatter
      }
    }

    Token(formatter.format(value), TokenType.TEMPORAL)
  }

  def tokenize(value: LocalDateTime): Token = tokenize(value: TemporalAccessor)
  def tokenize(value: LocalDate): Token = tokenize(value: TemporalAccessor)
}

// ============================================================================
// Universal tokenizer
// ============================================================================

final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenizeNull: Token = Token("NULL", TokenType.NULL)

  def tokenize(value: String): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Array[Byte]): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Int): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Long): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Double): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Float): Token = numericTokenizer.tokenize(value)
  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)
  def tokenize(value: java.math.BigDecimal): Token = numericTokenizer.tokenize(value)
  def tokenize(value: LocalDateTime): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: LocalDate): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: Tokenizable): Token = Token(value.toToken, TokenType.STRUCTURED)

  def tokenize(value: Any): Token = value match {
    case null => tokenizeNull
    case t: Tokenizable => tokenize(t)
    case s: String => tokenize(s)
    case b: Array[Byte] => tokenize(b)
    case d: Double => tokenize(d)
    case f: Float => tokenize(f)
    case i: Int => tokenize(i)
    case l: Long => tokenize(l)
    case bd: BigDecimal => tokenize(bd)
    case bd: java.math.BigDecimal => tokenize(bd)
    case dt: LocalDateTime => tokenize(dt)
    case d: LocalDate => tokenize(d)
    case other => Token(other.toString, TokenType.STRING, Map("fallback" -> true))
  }
}

// ============================================================================
// Token registry
// ============================================================================

final class TokenRegistry[T] {
  private val registry = mutable.Map.empty[String, TokenContainer[T]]
  private val handlers = ListBuffer.empty[T => Option[Token]]

  def register(key: String, container: TokenContainer[T]): Unit = {
    registry.update(key, container)
  }

  def addHandler(handler: T => Option[Token]): Unit = {
    handlers += handler
  }

  def process(key: String): List[Option[Token]] = {
    registry.get(key).map { container =>
      container.getAll.toList.map { item =>
        handlers.iterator
          .map(handler => handler(item))
          .collectFirst { case Some(token) => token }
      }
    }.getOrElse(Nil)
  }
}

// ============================================================================
// Functor and Monad
// ============================================================================

class TokenFunctor[+T](protected val valueOption: Option[T]) {
  def this(value: T) = this(Option(value))

  def map[U](func: T => U): TokenFunctor[U] =
    new TokenFunctor(valueOption.map(func))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] =
    valueOption.map(func).getOrElse(TokenFunctor.empty)

  def getOrElse(default: => T): T = valueOption.getOrElse(default)

  def get: T = valueOption.getOrElse(
    throw new NoSuchElementException("TokenFunctor is empty")
  )
}

object TokenFunctor {
  def apply[T](value: T): TokenFunctor[T] = new TokenFunctor(value)
  def empty[T]: TokenFunctor[T] = new TokenFunctor[T](None)
}

final class TokenMonad[+T](value: Option[T]) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] = {
    val result = for {
      func <- funcWrapped.valueOption
      v <- valueOption
    } yield func(v)

    new TokenMonad(result)
  }
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(Option(value))
}

// ============================================================================
// JSON tokenizer
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  def tokenize(value: Json): Token = {
    val jsonStr = if (pretty) value.spaces2 else value.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Json, path: String): Option[Token] =
    navigate(value, path.split("\\.").toList).map(tokenize)

  private def navigate(current: Json, parts: List[String]): Option[Json] =
    parts match {
      case Nil => Some(current)
      case head :: tail =>
        val next = current.asObject.flatMap(_.apply(head))
          .orElse(indexFromArray(current, head))

        next.flatMap(n => navigate(n, tail))
    }

  private def indexFromArray(current: Json, part: String): Option[Json] = {
    if (part.forall(_.isDigit)) {
      current.asArray.flatMap { arr =>
        val idx = part.toInt
        if (idx >= 0 && idx < arr.size) Some(arr(idx)) else None
      }
    } else {
      None
    }
  }
}

// ============================================================================
// Whitespace tokenizer
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) strip(word) else word
    val cased = if (lowercase) stripped.toLowerCase else stripped

    if (cased.length < minLength) None
    else {
      val bounded = maxLength match {
        case Some(limit) if cased.length > limit => cased.take(limit)
        case _ => cased
      }

      if (bounded.isEmpty) None else Some(bounded)
    }
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+")
    val tokens = ListBuffer.empty[Token]

    for ((word, index) <- words.zipWithIndex) {
      processToken(word).foreach { processed =>
        val token = Token(
          value = processed,
          tokenType = TokenType.STRING,
          metadata = Map("position" -> index, "original" -> word)
        )
        tokens += token
      }
    }

    tokens.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val result = ListBuffer.empty[(String, Int, Int)]
    var currentPos = 0

    for (word <- text.split("\\s+")) {
      val start = text.indexOf(word, currentPos)
      val end = if (start >= 0) start + word.length else currentPos

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).length

  private def strip(word: String): String =
    word.dropWhile(punctuation.contains)
      .reverse
      .dropWhile(punctuation.contains)
      .reverse
}

// ============================================================================
// Tokenizer builder
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers = ListBuffer.empty[String => String]
  private val validators = ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= entries
    this
  }

  def build(): T => Token = {
    val frozenNormalizers = normalizers.toList
    val frozenValidators = validators.toList
    val frozenMetadata = metadata.toMap

    (value: T) => {
      frozenValidators.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      val normalized = frozenNormalizers.foldLeft(value.toString) {
        case (acc, normalizer) => normalizer(acc)
      }

      Token(normalized, TokenType.STRING, frozenMetadata)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
